native=np.fromfile(sys.argv[2],np.float32).reshape(32,4096);x=native[2].copy();p='language_model.model.layers.3';a=p+'.self_attn';nrm=rms(x,get(p+'.input_layernorm.weight'));raw=(dq(a+'.q_proj')@nrm).reshape(16,512);gate=raw[:,256:];v=(dq(a+'.v_proj')@nrm).reshape(4,256);core=np.repeat(v,4,0);gated=core/(1+np.exp(-gate));op=dq(a+'.o_proj')@gated.reshape(-1);res=x+op;n2=rms(res,get(p+'.post_attention_layernorm.weight'));gg=dq(p+'.mlp.gate_proj')@n2;uu=dq(p+'.mlp.up_proj')@n2;down=dq(p+'.mlp.down_proj')@(gg/(1+np.exp(-gg))*uu);final=res+down;d=native[3];print('max',abs(final-d).max(),'mean',abs(final-d).mean(),'cos',final@d/np.linalg.norm(final)/np.linalg.norm(d),final[:8],d[:8])
